import{_ as l,o as a,c as e,am as r}from"./chunks/framework.CiF4W93w.js";const b=JSON.parse('{"title":"面试突击_常见面试题","description":"","frontmatter":{"title":"面试突击_常见面试题","excerpt":"进行一些面试题的自测","date":"2024-02-27 14:33:13","updated":"2024-02-27 14:33:13"},"headers":[],"relativePath":"Java面试准备/面试模拟辅助/面试突击_常见面试题.md","filePath":"Java面试准备/面试模拟辅助/面试突击_常见面试题.md","lastUpdated":null}'),t={name:"Java面试准备/面试模拟辅助/面试突击_常见面试题.md"};function o(n,i,h,s,u,c){return a(),e("div",null,[...i[0]||(i[0]=[r('<p>面试自测题</p><h3 id="java基础" tabindex="-1">Java基础 <a class="header-anchor" href="#java基础" aria-label="Permalink to &quot;Java基础&quot;">​</a></h3><ul><li>基础类型有哪些，说一下 int 类型占用多少字节</li><li>字节流和字符流有什么区别，读取视频一般是使用字节流还是字符流</li></ul><h3 id="java集合" tabindex="-1">Java集合 <a class="header-anchor" href="#java集合" aria-label="Permalink to &quot;Java集合&quot;">​</a></h3><ul><li>讲一下ArrayList 的底层原理</li><li>数组和集合之间如何转换</li><li>ArrayList 和 LinkedList 之间的区别</li><li>说一下 HashMap 的底层实现原理</li><li>讲述一下 HashMap 的 put 方法的具体流程</li><li>讲一讲 HashMap 的扩容机制</li><li>HashMap 的寻址算法和数组长度为什么是2 的 n 次幂</li><li>HashMap 在 1.7 情况下的多线程死循环问题如何解决（了解）</li><li>Collection 集合下哪些是线程安全的</li><li>HashTable 怎么实现线程安全的</li><li>TreeSet 是默认有序的吗</li><li>HashSet 的底层结构是怎么样的</li><li>Set 怎么变有序，除了 TreeSet 还有什么方式能够实现 Set 有序的操作</li></ul><h3 id="java并发" tabindex="-1">Java并发 <a class="header-anchor" href="#java并发" aria-label="Permalink to &quot;Java并发&quot;">​</a></h3><ul><li>线程和进程的区别？</li><li>并行和并发的区别？</li><li>讲一下线程创建的方式？Runable 和 Callable 的区别；strat 和 run 的区别。</li><li>线程包括哪些状态，状态之间是如何变化的</li><li>线程按顺序执行 join、notify 和 notifyall 的区别。</li><li>Java 中 wait 和 sleep 的区别。</li><li>如何停止一个正在运行的线程。</li><li>synchronized 关键字的底层原理。 <ul><li>基础回答</li><li>进阶回答</li></ul></li><li>谈谈 JMM (Java 内存模型)</li><li>你谈谈对 CAS 的理解</li><li>请谈谈你对 volatile 的理解（可见性，禁止指令重排序）</li><li>什么是 AQS</li><li>ReentantLock 的实现原理</li><li>synchronized 和 Lock 有什么区别</li><li>死锁产生的条件以及死锁排查方案</li><li>聊一下 ConcurrentHashMap</li><li>导致并发编程出现问题的根本原因是什么</li><li><strong>说一下线程池的创建方式</strong>（线程池的种类有哪些)</li><li>说一下线程池的核心参数（线程池的执行原理知道吗）</li><li>线程池中有哪些常见的阻塞队列</li><li>如何确认核心线程数</li><li>线程池的拒绝策略有哪些？</li><li>为什么不建议使用 Executor 创建线程池</li><li>讲述一下你们项目中哪里用到了线程池（异步线程）</li><li>如何控制某个方法允许并发访问线程的数量</li><li>谈谈你对 ThreadLocal 的理解</li></ul><h3 id="jvm" tabindex="-1">JVM <a class="header-anchor" href="#jvm" aria-label="Permalink to &quot;JVM&quot;">​</a></h3><ul><li>JVM是什么，讲一下运行流程</li><li>什么是程序计数器</li><li>介绍一下堆</li><li>什么是虚拟机栈</li><li>讲一下方法区</li><li>听过直接内存吗</li><li>什么是类加载器，什么是双亲委派机制</li><li>说一下类加载的执行过程</li><li>对象什么时候可以被垃圾器回收</li><li>JVM 垃圾回收算法有哪些</li><li>说一下 JVM 的分代回收</li><li>说一下 JVM 有哪些垃圾回收器</li><li>详细聊一下 G1 垃圾回收器</li><li>强引用、弱引用、软引用、虚引用的区别</li><li>JVM调优参数可以在哪里设置参数值</li><li>用的JVM调优的参数都有哪些</li><li>说一下 JVM 调优的工具</li><li>JVM 内存泄漏的排查思路</li><li>CPU 飙高的排查方案及其思路</li></ul><h3 id="mysql" tabindex="-1">MySql <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;MySql&quot;">​</a></h3><ul><li>如何定位慢查询</li><li>SQL 语句执行的很慢，如何分析</li><li>MySQL 的常见索引有哪些</li><li>组合索引有什么使用准则</li><li>索引底层怎么实现的</li><li>聚簇索引和非聚簇索引、回表查询、覆盖索引、超大分页优化</li><li>索引创建的原则</li><li>什么情况下索引会失效</li><li>谈一谈你对 SQL 优化的经验</li><li>事务的特性</li><li>并发事务问题、隔离级别</li><li>undo log 和 redo log 的区别</li><li>解释一下 MVCC</li><li>主从同步原理</li><li>分库分表</li></ul><h3 id="redis" tabindex="-1">Redis <a class="header-anchor" href="#redis" aria-label="Permalink to &quot;Redis&quot;">​</a></h3><ul><li>缓存穿透</li><li>缓存击穿</li><li>缓存雪崩</li><li>双写一致性</li><li>持久化</li><li>数据过期策略</li><li>数据淘汰策略</li><li>Redis 分布式锁（使用场景，实现原理 senx + redisson ）</li><li>主从复制</li><li>哨兵模式</li><li>分片集群</li><li>Redis 是单线程的，但是为什么还那么快</li></ul><h3 id="spring" tabindex="-1">Spring <a class="header-anchor" href="#spring" aria-label="Permalink to &quot;Spring&quot;">​</a></h3><ul><li>单例 Bean 是线程安全的吗</li><li>AOP 的相关面试题</li><li>事务失效的场景</li><li>Bean 的生命周期</li><li>Bean 的循环依赖（循环引用）</li><li>Spring 框架常见的注解（spring、SpringMVC、SpringBoot）</li><li>动态代理是基于什么方式实现的</li></ul><h3 id="springmvc" tabindex="-1">SpringMVC <a class="header-anchor" href="#springmvc" aria-label="Permalink to &quot;SpringMVC&quot;">​</a></h3><ul><li>讲述一下 SpringMVC 的执行流程</li></ul><h3 id="mybatis" tabindex="-1">Mybatis <a class="header-anchor" href="#mybatis" aria-label="Permalink to &quot;Mybatis&quot;">​</a></h3><ul><li>讲一下 Mybatis 的执行流程</li><li>讲一下 Mybatis 延迟加载使用及其原理</li><li>讲一下 Mybatis 一级、二级缓存</li></ul><h3 id="springboot" tabindex="-1">SpringBoot <a class="header-anchor" href="#springboot" aria-label="Permalink to &quot;SpringBoot&quot;">​</a></h3><ul><li>SpringBoot 的自动配置原理讲一下</li><li>SpringBoot 的启动流程讲一下，讲一下 SpringBoot 的自动装配</li><li>SpringBoot 有哪几种配置文件, yml 和 propertiey 配置文件哪个优先级高一点</li></ul><h3 id="springcloud" tabindex="-1">SpringCloud <a class="header-anchor" href="#springcloud" aria-label="Permalink to &quot;SpringCloud&quot;">​</a></h3><ul><li>Spring、SpringBoot、SpringCloud 这三个有什么区别</li><li>SpringCloud 有有哪些核心组件</li><li>Nacos 的 Space ID 干嘛的</li><li>Nacos 的全局策略了解吗</li><li>Nacos 调用服务是通过什么方式来实现的（负载均衡）</li><li>讲述一下注册中心 Eureka、Nacos 的工作流程</li><li>你们项目中负载均衡是如何实现的，讲述一下 Ribbon 负载均衡（包括常见负载均衡策略，如何自定义负载均衡策略）</li><li>Gateway 有哪些核心组件</li><li>OpenFeign 底层基于什么实现的（RPC）</li><li>讲一下服务雪崩和熔断降级</li><li>微服务的监控 skywalking （跳过，说不了解）</li><li>微服务的限流（漏桶算法，令牌桶算法）讲一下你们项目中如何处理的</li><li>分布式系统理论 CAP 和 Base</li><li>分布式事务的解决方案有哪些</li><li>分布式服务的接口幂等性如何设计</li><li>你们项目中使用了什么分布式任务调度 xxl-job</li></ul><h3 id="mq" tabindex="-1">MQ <a class="header-anchor" href="#mq" aria-label="Permalink to &quot;MQ&quot;">​</a></h3><h4 id="rabbitmq" tabindex="-1">RabbitMQ <a class="header-anchor" href="#rabbitmq" aria-label="Permalink to &quot;RabbitMQ&quot;">​</a></h4><ul><li>如何保证消息不丢失</li><li>消息的重复消费问题如何解决</li><li>RabbitMQ 的延迟队列有了解过吗（讲一下 RabbitMQ 中的死信交换机）</li><li>消息堆积问题怎么解决</li><li>RabbitMQ 的高可用机制有了解过吗</li></ul><h4 id="rocketmq" tabindex="-1">RocketMQ <a class="header-anchor" href="#rocketmq" aria-label="Permalink to &quot;RocketMQ&quot;">​</a></h4><ul><li>讲一下 RocketMQ 的基本架构（RocketMQ 有哪些核心组件）</li><li>讲一下 RocketMQ 的消息模型？</li><li>消息的消费模式了解吗？</li><li>如何保证消息的可用性/可靠性/不丢失呢</li><li>消息重复问题如何处理。</li><li>消息堆压问题如何解决</li><li>顺序消息如何实现</li><li>如何实现消息过滤</li><li>RocketMQ 是如何实现延时消息的</li><li>怎么实现消息的分布式事务的，半消息？</li><li>死信队列了解吗</li><li>如何保证RocketMQ的高可用？</li><li>说一下RocketMQ的整体工作流程？</li><li>消息刷盘怎么实现的呢？</li></ul><h3 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><h3 id="elasticsearch" tabindex="-1">Elasticsearch <a class="header-anchor" href="#elasticsearch" aria-label="Permalink to &quot;Elasticsearch&quot;">​</a></h3><ul><li>Elasticsezrch 是什么，能做什么，讲一下ES 的基础概念</li><li>Lucene 是什么</li><li>了解倒排索引吗</li><li>分词器有哪些，由什么组成</li><li>ES 常见的数据类型有哪些</li></ul><h3 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h3><ul><li>Vue 的跨域了解吗</li><li>Vue 的双向绑定了解吗</li><li>computer 和 watch 有什么区别，watch 深度监听了解吗</li><li>vue 路由有几种方式</li></ul><h3 id="其他常见面试题" tabindex="-1">其他常见面试题 <a class="header-anchor" href="#其他常见面试题" aria-label="Permalink to &quot;其他常见面试题&quot;">​</a></h3><ul><li>Linux 的常见命令有哪些</li></ul><h3 id="设计模式" tabindex="-1">设计模式 <a class="header-anchor" href="#设计模式" aria-label="Permalink to &quot;设计模式&quot;">​</a></h3><ul><li>讲一下工厂设计模式中的简单工厂模式</li><li>讲一下抽象工厂模式、工厂方法模式</li><li>讲一下策略模式</li><li>讲一下责任链模式</li></ul><h3 id="技术场景" tabindex="-1">技术场景 <a class="header-anchor" href="#技术场景" aria-label="Permalink to &quot;技术场景&quot;">​</a></h3><ul><li>讲一下单点登陆的实现</li><li>权限认证是如何实现的</li><li>上传数据的安全你们是如何控制的</li><li>遇到了哪些比较棘手的问题，怎么解决的</li><li>你们项目中日志是怎么采集的</li><li>常见日志的命令</li><li>生产问题怎么排查</li><li>怎么快速定位系统的瓶颈</li></ul><h3 id="项目面试题" tabindex="-1">项目面试题 <a class="header-anchor" href="#项目面试题" aria-label="Permalink to &quot;项目面试题&quot;">​</a></h3><ul><li>项目描述借鉴一下这个： <a href="https://www.bilibili.com/video/BV1iH4y1V7G5" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1iH4y1V7G5</a></li></ul><h3 id="软性问题" tabindex="-1">软性问题 <a class="header-anchor" href="#软性问题" aria-label="Permalink to &quot;软性问题&quot;">​</a></h3><ul><li>离职的原因说一下</li></ul><hr><p>参考</p><ul><li><a href="http://svip.iocoder.cn/tags/interview" target="_blank" rel="noreferrer">http://svip.iocoder.cn/tags/interview</a></li><li><a href="https://www.yuque.com/snailclimb/mf2z3k/xkhs3e" target="_blank" rel="noreferrer">https://www.yuque.com/snailclimb/mf2z3k/xkhs3e</a></li><li><a href="https://javaguide.cn/home.html" target="_blank" rel="noreferrer">https://javaguide.cn/home.html</a></li><li><a href="https://javaguide.cn/java/jvm/jvm-in-action.html" target="_blank" rel="noreferrer">https://javaguide.cn/java/jvm/jvm-in-action.html</a></li></ul>',46)])])}const p=l(t,[["render",o]]);export{b as __pageData,p as default};
